/// The commands this module owns.
pub const COMMANDS: &[&str] = &[
    "modify",
    "match_properties",
    "move",
    "copy",
    "rotate",
    "mirror",
    "corner",
    "split",
    "fillet",
    "align",
    "delete",
    "insert",
    "link",
    "reload",
    "purge",
