def walk(path, x, y, depth):
    if x == y:
        return
    if isinstance(x, dict) and isinstance(y, dict) and depth > 0:
        kx, ky = list(x.keys()), list(y.keys())
        for k in kx:
            if k not in y:
                print('  -', path + '/' + k, json.dumps(x[k], ensure_ascii=False)[:200])
        for k in ky:
            if k not in x:
                print('  +', path + '/' + k, json.dumps(y[k], ensure_ascii=False)[:400])
        common_x = [k for k in kx if k in y]
        common_y = [k for k in ky if k in x]
        if common_x != common_y:
            print('  ORDER', path, common_x[:20], '->', common_y[:20])
        for k in ky:
            if k in x:
                walk(path + '/' + k, x[k], y[k], depth - 1)
    else:
        print('  ~', path, json.dumps(x, ensure_ascii=False)[:400], '->', json.dumps(y, ensure_ascii=False)[:400])

if os.path.exists(os.path.join(d, 'out.bimcraft')):
