#!/usr/bin/env python3
"""rem.py [-x exe] in.bimcraft 'purge {...}' : print the removed list one per line."""
import json, sys, subprocess, tempfile, shutil, os
exe = '/workspace/executable'
a = sys.argv[1:]
if a[0] == '-x':
    exe = a[1]; a = a[2:]
src, cmds = a[0], a[1:]
d = tempfile.mkdtemp(prefix='rem')
args = [exe, 'run']
if src != '-':
    shutil.copy(src, os.path.join(d, 'in.bimcraft'))
    args.append('in.bimcraft')
for c in cmds:
    args += ['--cmd', c]
p = subprocess.run(args, cwd=d, capture_output=True, text=True)
out = p.stdout.splitlines()
if src != '-':
    out = out[1:]
for l in out:
    try:
        v = json.loads(l)
    except Exception:
        print(l); continue
    if isinstance(v, dict) and 'removed' in v:
