#!/usr/bin/env python3
"""multirem.py [-x exe] [-g grep] -f cmds.txt in.bimcraft: run each line (' ;; ' separated commands); print
replies compactly, a purge reply as its removed list without family types (unless -a)."""
import json, sys, subprocess, tempfile, shutil, os, re
exe = '/workspace/executable'
a = sys.argv[1:]
cmds = []
allft = False
grep = None
while a and a[0].startswith('-'):
    if a[0] == '-x':
        exe = a[1]; a = a[2:]
    elif a[0] == '-f':
        cmds += [l.rstrip('\n') for l in open(a[1]) if l.strip() and not l.startswith('#')]; a = a[2:]
    elif a[0] == '-a':
        allft = True; a = a[1:]
    elif a[0] == '-g':
        grep = a[1]; a = a[2:]
    else:
        break
src = a[0]
cmds += a[1:]
for c in cmds:
    d = tempfile.mkdtemp(prefix='mr')
    args = [exe, 'run']
    if src != '-':
        shutil.copy(src, os.path.join(d, 'in.bimcraft'))
        args.append('in.bimcraft')
    for x in c.split(' ;; '):
        args += ['--cmd', x]
    for f in ('red.png', 'green.png', 'blue.png'):
        shutil.copy('/tmp/edit-library/' + f, d)
    p = subprocess.run(args, cwd=d, capture_output=True, text=True)
    out = p.stdout.splitlines()
    if src != '-':
        out = out[1:]
    print('$', c[:300])
    for l in out:
        try:
            v = json.loads(l)
        except Exception:
            print('  ', l[:300]); continue
        if isinstance(v, dict) and 'removed' in v:
            items = [r['kind'] + ':' + r['name'] for r in v['removed'] if allft or r['kind'] != 'family type']
            if grep:
                items = [i for i in items if re.search(grep, i)]
            print('   count=%d dry=%s :: %s' % (v['count'], v['dry_run'], ' | '.join(items)))
        else:
            print('  ', json.dumps(v, ensure_ascii=False)[:400])
    if p.stderr:
        print('   ERR', p.stderr.strip()[:500])
    shutil.rmtree(d)

