//! What Purge Unused, Delete Type, Rename Type and Match Properties share: the types of a
//! category as the original finds them from a category's name, families and their types, what
//! uses them, and the original's long errors.

use crate::json::{Map, Value};
use crate::project::Project;

/// The longest error the original gives whole; past it, the rest is counted.
const MAX_ERROR: usize = 2000;

/// Marks an error the original's model check gives (after the command), which isn't clipped.
const CHECK: char = '\u{1}';

/// An error as the original's model check gives it after the command: said whole.
pub fn check_error(e: String) -> String {
    format!("{}{}", CHECK, e)
}

/// A command's error past 2000 characters: its first 2000 and how many more there were (what the
/// model's check finds is said whole).
pub fn clip_error(e: String) -> String {
    if let Some(rest) = e.strip_prefix(CHECK) {
        return rest.to_string();
    }
    let n = e.chars().count();
    if n <= MAX_ERROR {
        return e;
    }
    let mut out: String = e.chars().take(MAX_ERROR).collect();
    out.push_str(&format!("… ({} more characters)", n - MAX_ERROR));
    out
}

/// A category as the type commands read one: its ASCII letters and digits, lowercased, without
/// the s's it ends in (`Structural Columns`, `structural_column` and `structuralcolumn` are one).
pub fn norm_category(s: &str) -> String {
    let t: String = s.chars().filter(|c| c.is_ascii_alphanumeric()).collect::<String>().to_ascii_lowercase();
    t.trim_end_matches('s').to_string()
}

/// Where a category's types are kept.
#[derive(Clone, Debug, PartialEq)]
pub enum Loc {
    /// `types` under this key (`wall`, `structural_column`…).
    Types(String),
    /// `types.runs` under this key (`beam`, `pipe`…).
    Runs(String),
    /// A section of drafting types (`text_types`, `dimension_types`, `region_types`).
    Styles(&'static str),
}

/// The categories of `types` (and `types.runs`) by their keys: (normalised name, where).
pub fn type_categories(pr: &Project) -> Vec<(String, Loc)> {
    let mut out = Vec::new();
    if let Some(types) = pr.section("types") {
        for (k, v) in types.iter() {
            if k == "runs" {
                continue;
            }
            if v.as_obj().is_some() {
                out.push((norm_category(k), Loc::Types(k.clone())));
            }
        }
        if let Some(runs) = types.get("runs").and_then(|r| r.as_obj()) {
            for (k, v) in runs.iter() {
                if v.as_obj().is_some() {
                    out.push((norm_category(k), Loc::Runs(k.clone())));
                }
            }
        }
    }
    out
}

/// Where the types of a (normalised) category are; with `styles`, text, dimension and filled
/// region types too.
pub fn locate(pr: &Project, cat: &str, styles: bool) -> Option<Loc> {
    if let Some((_, loc)) = type_categories(pr).into_iter().find(|(n, _)| n == cat) {
        return Some(loc);
    }
    if !styles {
        return None;
    }
    match cat {
        "text" => Some(Loc::Styles("text_types")),
        "dimension" => Some(Loc::Styles("dimension_types")),
        "region" => Some(Loc::Styles("region_types")),
        _ => None,
    }
}

/// The types kept there.
pub fn loc_map<'a>(pr: &'a Project, loc: &Loc) -> Option<&'a Map> {
    match loc {
        Loc::Types(k) => pr.section("types")?.get(k)?.as_obj(),
        Loc::Runs(k) => pr.section("types")?.get("runs")?.get(k)?.as_obj(),
        Loc::Styles(s) => pr.section(s),
    }
}

pub fn loc_map_mut<'a>(pr: &'a mut Project, loc: &Loc) -> Option<&'a mut Map> {
    match loc {
        Loc::Types(k) => pr.get_mut("types")?.get_mut(k)?.as_obj_mut(),
        Loc::Runs(k) => pr.get_mut("types")?.get_mut("runs")?.get_mut(k)?.as_obj_mut(),
        Loc::Styles(s) => pr.get_mut(s)?.as_obj_mut(),
    }
}

/// Their names, sorted.
pub fn loc_names(pr: &Project, loc: &Loc) -> Vec<String> {
    let mut v: Vec<String> = loc_map(pr, loc).map(|m| m.keys().cloned().collect()).unwrap_or_default();
    v.sort();
    v
}

/// The library kind of a (normalised) category's types: `type:wall`, `type:structuralcolumn`.
pub fn type_kind(cat: &str) -> String {
    format!("type:{}", cat)
}

/// "1 time", "4 times".
pub fn times(n: usize) -> String {
    if n == 1 {
        "1 time".to_string()
    } else {
        format!("{} times", n)
    }
}

/// How many elements have this as their `type`.
pub fn uses_as_type(pr: &Project, guid: Option<&str>) -> usize {
    let Some(g) = guid else { return 0 };
    pr.elements.values().filter(|e| e.get("type").and_then(|t| t.as_str()) == Some(g)).count()
}

/// How many elements are of this family.
pub fn uses_as_family(pr: &Project, guid: Option<&str>) -> usize {
    let Some(g) = guid else { return 0 };
    pr.elements.values().filter(|e| e.get("family").and_then(|t| t.as_str()) == Some(g)).count()
}

// ---------------------------------------------------------------- families

pub fn families(pr: &Project) -> Option<&Map> {
    pr.section("families")
}

/// The project's families' names, sorted.
pub fn family_names(pr: &Project) -> Vec<String> {
    let mut v: Vec<String> = families(pr).map(|m| m.keys().cloned().collect()).unwrap_or_default();
    v.sort();
    v
}

/// A family's types' names, sorted.
pub fn family_type_names(fam: &Value) -> Vec<String> {
    let mut v: Vec<String> = fam.get("types").and_then(|t| t.as_obj()).map(|m| m.keys().cloned().collect()).unwrap_or_default();
    v.sort();
    v
}

/// A family's parameters' names, in order.
pub fn family_param_names(fam: &Value) -> Vec<String> {
    fam.get("parameters")
        .and_then(|a| a.as_arr())
        .map(|a| a.iter().filter_map(|x| x.get("name").and_then(|n| n.as_str()).map(|n| n.to_string())).collect())
        .unwrap_or_default()
}

/// How the library names one of a family's types or parameters: `Bed: 900 x 2000`.
pub fn qualified(family: &str, name: &str) -> String {
    format!("{}: {}", family, name)
}

/// Takes the library entry of this kind and name away.
pub fn lib_remove(pr: &mut Project, kind: &str, name: &str) {
    if let Some(id) = pr.lib_find(kind, name) {
        pr.library.remove(&id);
    }
}

/// Renames the library entry of this kind and name.
pub fn lib_rename(pr: &mut Project, kind: &str, from: &str, to: &str) {
    if let Some(id) = pr.lib_find(kind, from) {
        if let Some(e) = pr.library.get_mut(&id) {
            e.set("name", Value::s(to));
        }
    }
}

/// Takes a family away, and its library entries with it: its own, its types' and its
/// parameters'.
pub fn remove_family(pr: &mut Project, name: &str) {
    let Some(fam) = families(pr).and_then(|m| m.get(name)).cloned() else { return };
    for t in family_type_names(&fam) {
        lib_remove(pr, "family-type", &qualified(name, &t));
    }
    for p in family_param_names(&fam) {
        lib_remove(pr, "family-parameter", &qualified(name, &p));
    }
    lib_remove(pr, "family", name);
    if let Some(m) = pr.get_mut("families").and_then(|v| v.as_obj_mut()) {
        m.remove(name);
    }
}

/// Takes one of a family's types away, and its library entry.
pub fn remove_family_type(pr: &mut Project, family: &str, t: &str) {
    if let Some(types) = pr
        .get_mut("families")
        .and_then(|v| v.get_mut(family))
        .and_then(|f| f.get_mut("types"))
        .and_then(|t| t.as_obj_mut())
    {
        types.remove(t);
    }
    lib_remove(pr, "family-type", &qualified(family, t));
}

/// A key of a map renamed in place, the map kept in sorted order.
pub fn rename_key_sorted(m: &mut Map, from: &str, to: &str) {
    if let Some(v) = m.remove(from) {
        m.insert_sorted(to, v);
    }
}

/// A name that reads as a GUID (8-4-4-4-12 hex digits, braces or not, any case).
pub fn is_guid_name(s: &str) -> bool {
    crate::styles::electrical::as_guid(s).is_some()
}

//! Delete Type and Rename Type: a type of a category, or a family and its types.

use super::common::*;
use super::library_util::*;
use crate::commands::params::opt_text;
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

const GIVE: &str = "give `category` and `type`, or `family`, or `family` and `type`";

pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    let r = if cid == "delete_type" { delete(s, p) } else { rename(s, p) };
    r.map_err(clip_error)
}

// ---------------------------------------------------------------- delete_type

fn delete(s: &mut Session, p: &Value) -> R<Value> {
    const C: &str = "delete_type";
    let category = opt_text(p, C, "category")?;
    let family = opt_text(p, C, "family")?;
    let typ = opt_text(p, C, "type")?;
    let pr = &mut s.project;
    match (category, family, typ) {
        (Some(c), None, Some(t)) => delete_category_type(pr, &c, &t),
        (None, Some(f), None) => delete_family(pr, &f),
        (None, Some(f), Some(t)) => delete_family_type(pr, &f, &t),
        _ => Err(format!("{}: {}", C, GIVE)),
    }
}

fn deleted(kind: &str, name: &str) -> Value {
    jobj! {"deleted" => jobj! {"kind" => kind, "name" => name}}
}

fn delete_category_type(pr: &mut Project, c: &str, t: &str) -> R<Value> {
    const C: &str = "delete_type";
    let cat = norm_category(c);
    let Some(loc) = locate(pr, &cat, true) else {
        return Err(format!("{}: there is no {} type `{}`", C, cat, t));
    };
    let names = loc_names(pr, &loc);
    if !names.iter().any(|n| n == t) {
        return Err(format!("{}: there is no {} type `{}` (there are: {})", C, cat, t, names.join(", ")));
    }
    // text, dimension and filled region types are found where they are, and asked after as if
    // they were among `types`: none of their notes is counted, and nothing is taken away
    let drafting = matches!(loc, Loc::Styles(_));
    let kind = type_kind(&cat);
    if !drafting {
        let guid = pr.lib_guid(&kind, t);
        let n = uses_as_type(pr, guid.as_deref());
        if n > 0 {
            return Err(format!(
                "{}: {} type `{}` is used {}: change or delete what uses it first",
                C,
                cat,
                t,
                times(n)
            ));
        }
    }
    if names.len() == 1 {
        return Err(format!("{}: `{}` is the last {} type: a {} needs one; make another first", C, t, cat, cat));
    }
    if !drafting {
        if let Some(m) = loc_map_mut(pr, &loc) {
            m.remove(t);
        }
        lib_remove(pr, &kind, t);
    }
    Ok(deleted(&format!("{} type", cat), t))
}

fn delete_family(pr: &mut Project, f: &str) -> R<Value> {
    const C: &str = "delete_type";
    let names = family_names(pr);
    if !names.iter().any(|n| n == f) {
        return Err(format!("{}: there is no family `{}` (there are: {})", C, f, names.join(", ")));
    }
    let guid = pr.lib_guid("family", f);
    let n = uses_as_family(pr, guid.as_deref());
    if n > 0 {
        return Err(format!("{}: family `{}` is used {}: change or delete what uses it first", C, f, times(n)));
    }
    remove_family(pr, f);
    Ok(deleted("family", f))
}

fn delete_family_type(pr: &mut Project, f: &str, t: &str) -> R<Value> {
    const C: &str = "delete_type";
    let Some(fam) = families(pr).and_then(|m| m.get(f)).cloned() else {
        return Err(format!("{}: there is no family `{}`", C, f));
    };
    let types = family_type_names(&fam);
    if !types.iter().any(|n| n == t) {
        return Err(format!("{}: family `{}` has no type `{}` (there are: {})", C, f, t, types.join(", ")));
    }
    let q = qualified(f, t);
    let guid = pr.lib_guid("family-type", &q);
    let n = uses_as_type(pr, guid.as_deref());
    if n > 0 {
        return Err(format!("{}: family type `{}` is used {}: change or delete what uses it first", C, q, times(n)));
    }
    if types.len() == 1 {
        return Err(format!("{}: `{}` is its family's last type: delete the family", C, q));
    }
    remove_family_type(pr, f, t);
    Ok(deleted("family type", &q))
}

// ---------------------------------------------------------------- rename_type

fn rename(s: &mut Session, p: &Value) -> R<Value> {
    const C: &str = "rename_type";
    crate::styles::common::check_keys(p, C, &["category", "family", "type", "name"])?;
    let name = match opt_text(p, C, "name")? {
        Some(n) if !n.trim().is_empty() => n.trim().to_string(),
        _ => return Err(format!("{}: `name` is required: the type's new name", C)),
    };
    let category = opt_text(p, C, "category")?;
    let family = opt_text(p, C, "family")?;
    let typ = opt_text(p, C, "type")?;
    let pr = &mut s.project;
    match (category, family, typ) {
        (Some(c), None, Some(t)) => rename_category_type(pr, &c, &t, &name),
        (None, Some(f), None) => rename_family(pr, &f, &name),
        (None, Some(f), Some(t)) => rename_family_type(pr, &f, &t, &name),
        _ => Err(format!("{}: {}", C, GIVE)),
    }
}

fn renamed(from: &str, kind: &str, to: &str) -> Value {
    jobj! {"renamed" => jobj! {"from" => from, "kind" => kind, "to" => to}}
}

fn rename_category_type(pr: &mut Project, c: &str, t: &str, name: &str) -> R<Value> {
    const C: &str = "rename_type";
    let cat = norm_category(c);
    let Some(loc) = locate(pr, &cat, false) else {
        return Err(format!("{}: there is no {} type `{}`", C, cat, t));
    };
    let names = loc_names(pr, &loc);
    if !names.iter().any(|n| n == t) {
        return Err(format!("{}: there is no {} type `{}` (there are: {})", C, cat, t, names.join(", ")));
    }
    let kind_word = format!("{} type", cat);
    if name == t {
        return Ok(renamed(t, &kind_word, t));
    }
    if names.iter().any(|n| n == name) {
        return Err(format!("{}: there's already a {} `{}`", C, kind_word, name));
    }
    if let Some(m) = loc_map_mut(pr, &loc) {
        rename_key_sorted(m, t, name);
    }
    lib_rename(pr, &type_kind(&cat), t, name);
    // the model's rule that a library name isn't a GUID, which the original checks after it
    if is_guid_name(name) {
        return Err(check_error(format!("{} `{}`: a name isn't a GUID; name it otherwise", kind_word, name)));
    }
    Ok(renamed(t, &kind_word, name))
}

fn rename_family_type(pr: &mut Project, f: &str, t: &str, name: &str) -> R<Value> {
    const C: &str = "rename_type";
    let Some(fam) = families(pr).and_then(|m| m.get(f)).cloned() else {
        return Err(format!("{}: there is no family `{}`", C, f));
    };
    let types = family_type_names(&fam);
    if !types.iter().any(|n| n == t) {
        return Err(format!("{}: family `{}` has no type `{}` (there are: {})", C, f, t, types.join(", ")));
    }
    if name == t {
        return Ok(renamed(&qualified(f, t), "family type", t));
    }
    if types.iter().any(|n| n == name) {
        return Err(format!("{}: there's already a family type `{}`", C, name));
    }
    if let Some(m) = pr
        .get_mut("families")
        .and_then(|v| v.get_mut(f))
        .and_then(|x| x.get_mut("types"))
        .and_then(|x| x.as_obj_mut())
    {
        rename_key_sorted(m, t, name);
    }
    lib_rename(pr, "family-type", &qualified(f, t), &qualified(f, name));
    Ok(renamed(t, "family type", name))
}

/// A family on its own isn't renamed here: only its own name back, or a name another family
/// has, is answered; anything else isn't found.
fn rename_family(pr: &mut Project, f: &str, name: &str) -> R<Value> {
    const C: &str = "rename_type";
    let names = family_names(pr);
    if !names.iter().any(|n| n == f) {
        return Err(format!("{}: there is no family `{}` (there are: {})", C, f, names.join(", ")));
    }
    if name == f {
        return Ok(renamed(f, "family", f));
    }
    if names.iter().any(|n| n == name) {
        return Err(format!("{}: there's already a family `{}`", C, name));
    }
    Err(format!("{}: there is no family `{}`", C, f))
}

//! Purge Unused: what nothing uses, taken out.
//!
//! Each round finds, in the project as the round finds it, what nothing uses of each kind asked
//! for (types of categories, families, families' types, materials, pictures, view filters, view
//! templates, in that order, each sorted by name), and takes it all out; then again, for what
//! that left unused (a material only a purged type was made of, the picture of a purged
//! material, a filter only a purged template applied), until a round finds nothing.

use super::common::*;
use super::library_util::*;
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;
use std::collections::HashSet;

const KINDS: &[&str] = &["type", "family", "material", "picture", "filter", "template"];

/// The type a category keeps when nothing uses any of its types: the one a new element of it
/// takes, the starter's (by name), or else its first.
fn preferred(cat: &str) -> Option<&'static str> {
    Some(match cat {
        "wall" => "Generic - 200mm",
        "floor" => "Generic - 200mm",
        "door" => "Single 900 x 2100",
        "window" => "Fixed 1200 x 1500",
        "column" => "Rectangular 400 x 400",
        "roof" => "Generic - 300mm",
        "ceiling" => "Generic - 20mm",
        "railing" => "Railing - 1000mm",
        "structuralcolumn" => "Concrete 300 x 300",
        "footing" => "Footing 1200 x 1200",
        "beam" => "Beam 200 x 500",
        "stripfooting" => "Strip 600 x 300",
        "pipe" => "PVC 50",
        "duct" => "Rectangular 400 x 300",
        "conduit" => "PVC 25",
        "cabletray" => "Perforated 100 x 50",
        "wire" => "Wire 2.5",
        "downconductor" => "Steel 8",
        "groundconductor" => "Copper 9",
        "cable" => "Cat6",
        _ => return None,
    })
}

/// Something purge takes out.
enum Item {
    CategoryType { cat: String, loc: Loc, name: String },
    Family(String),
    FamilyType { family: String, name: String },
    Material(String),
    Picture(String),
    Filter(String),
    Template(String),
}

impl Item {
    /// (kind, name) as the reply lists it.
    fn label(&self) -> (String, String) {
        match self {
            Item::CategoryType { cat, name, .. } => (format!("{} type", cat), name.clone()),
            Item::Family(n) => ("family".into(), n.clone()),
            Item::FamilyType { family, name } => ("family type".into(), qualified(family, name)),
            Item::Material(n) => ("material".into(), n.clone()),
            Item::Picture(n) => ("picture".into(), n.clone()),
            Item::Filter(n) => ("view filter".into(), n.clone()),
            Item::Template(n) => ("view template".into(), n.clone()),
        }
    }
}

fn kinds_param(p: &Value) -> R<Vec<String>> {
    match p.get("kinds") {
        None | Some(Value::Null) => Ok(vec!["type".to_string(), "family".to_string()]),
        Some(Value::Arr(a)) => {
            let mut out: Vec<String> = Vec::new();
            for v in a {
                match v.as_str() {
                    Some(k) if KINDS.contains(&k) => {
                        if !out.iter().any(|x| x == k) {
                            out.push(k.to_string());
                        }
                    }
                    _ => {
                        return Err(format!(
                            "purge: `kinds` holds {}, not {}",
                            KINDS.join(", "),
                            v.to_compact()
                        ))
                    }
                }
            }
            Ok(out)
        }
        Some(v) => Err(format!("purge: `kinds` is a list of what to purge, not {}", v.to_compact())),
    }
}

pub fn run(s: &mut Session, p: &Value) -> R<Value> {
    let kinds = kinds_param(p)?;
    let dry_run = crate::commands::params::opt_bool(p, "purge", "dry_run")?.unwrap_or(false);
    let mut pr = s.project.clone();
    let mut removed: Vec<Value> = Vec::new();
    let mut seen: HashSet<(String, String)> = HashSet::new();
    loop {
        let items = unused(&pr, &kinds);
        let mut any = false;
        for it in &items {
            let label = it.label();
            if !seen.insert(label.clone()) {
                continue;
            }
            any = true;
            take_out(&mut pr, it);
            removed.push(jobj! {"kind" => label.0, "name" => label.1});
        }
        if !any {
            break;
        }
    }
    if !dry_run {
        s.project = pr;
    }
    Ok(jobj! {"count" => removed.len(), "dry_run" => dry_run, "removed" => Value::Arr(removed)})
}

/// Every string a value holds, anywhere in it.
fn strings<'a>(v: &'a Value, out: &mut HashSet<&'a str>) {
    match v {
        Value::Str(s) => {
            out.insert(s.as_str());
        }
        Value::Arr(a) => a.iter().for_each(|x| strings(x, out)),
        Value::Obj(m) => m.items.iter().for_each(|(_, x)| strings(x, out)),
        _ => {}
    }
}

fn sorted_keys(pr: &Project, section: &str) -> Vec<String> {
    let mut v: Vec<String> = pr.section(section).map(|m| m.keys().cloned().collect()).unwrap_or_default();
    v.sort();
    v
}

fn used_guid(pr: &Project, kind: &str, name: &str, used: &HashSet<&str>) -> bool {
    pr.lib_guid(kind, name).map(|g| used.contains(g.as_str())).unwrap_or(false)
}

/// What nothing uses, of the kinds asked for, in the order the reply lists it.
fn unused(pr: &Project, kinds: &[String]) -> Vec<Item> {
    let has = |k: &str| kinds.iter().any(|x| x == k);
    let mut out: Vec<Item> = Vec::new();
    // what elements are of: their types and families
    let mut el_types: HashSet<&str> = HashSet::new();
    let mut el_families: HashSet<&str> = HashSet::new();
    for e in pr.elements.values() {
        if let Some(t) = e.get("type").and_then(|t| t.as_str()) {
            el_types.insert(t);
        }
        if let Some(f) = e.get("family").and_then(|t| t.as_str()) {
            el_families.insert(f);
        }
    }
    // types of categories: a category none of whose types is used keeps one
    if has("type") {
        let mut cats = type_categories(pr);
        cats.sort_by(|a, b| a.0.cmp(&b.0));
        for (cat, loc) in cats {
            let names = loc_names(pr, &loc);
            let kind = type_kind(&cat);
            let used: Vec<bool> = names.iter().map(|n| used_guid(pr, &kind, n, &el_types)).collect();
            let keep: Option<String> = if used.iter().any(|u| *u) {
                None
            } else {
                preferred(&cat)
                    .filter(|p| names.iter().any(|n| n == p))
                    .map(|p| p.to_string())
                    .or_else(|| names.first().cloned())
            };
            for (n, u) in names.iter().zip(used.iter()) {
                if !*u && keep.as_deref() != Some(n.as_str()) {
                    out.push(Item::CategoryType { cat: cat.clone(), loc: loc.clone(), name: n.clone() });
                }
            }
        }
    }
    // families
    let mut families_out: HashSet<String> = HashSet::new();
    if has("family") {
        for f in family_names(pr) {
            if !used_guid(pr, "family", &f, &el_families) {
                families_out.insert(f.clone());
                out.push(Item::Family(f));
            }
        }
    }
    // the types of the families that stay: a family none of whose types is used keeps its last
    if has("type") {
        for f in family_names(pr) {
            if families_out.contains(&f) {
                continue;
            }
            let Some(fam) = families(pr).and_then(|m| m.get(&f)) else { continue };
            let names = family_type_names(fam);
            let used: Vec<bool> = names.iter().map(|t| used_guid(pr, "family-type", &qualified(&f, t), &el_types)).collect();
            let keep: Option<String> = if used.iter().any(|u| *u) { None } else { names.last().cloned() };
            for (t, u) in names.iter().zip(used.iter()) {
                if !*u && keep.as_deref() != Some(t.as_str()) {
                    out.push(Item::FamilyType { family: f.clone(), name: t.clone() });
                }
            }
        }
    }
    // materials: in a type (its layers, a run's), in a family, or painted on an element
    if has("material") {
        let mut used: HashSet<&str> = HashSet::new();
        if let Some(v) = pr.get("types") {
            strings(v, &mut used);
        }
        if let Some(v) = pr.get("families") {
            strings(v, &mut used);
        }
        for e in pr.elements.values() {
            if let Some(paint) = e.get("params").and_then(|p| p.get("Paint")) {
                strings(paint, &mut used);
            }
        }
        for m in sorted_keys(pr, "materials") {
            if !used_guid(pr, "material", &m, &used) {
                out.push(Item::Material(m));
            }
        }
    }
    // pictures: what a material's texture is made of
    if has("picture") {
        let mut used: HashSet<&str> = HashSet::new();
        if let Some(v) = pr.get("materials") {
            strings(v, &mut used);
        }
        for id in sorted_keys(pr, "images") {
            if !used_guid(pr, "picture", &id, &used) {
                out.push(Item::Picture(id));
            }
        }
    }
    // what views' graphics name: filters and templates (and the filters templates apply)
    let mut graphics: HashSet<&str> = HashSet::new();
    if has("filter") || has("template") {
        for e in pr.elements.values() {
            if let Some(g) = e.get("graphics") {
                strings(g, &mut graphics);
            }
        }
    }
    if has("filter") {
        let mut used = graphics.clone();
        if let Some(v) = pr.get("view_templates") {
            strings(v, &mut used);
        }
        for f in sorted_keys(pr, "view_filters") {
            if !used_guid(pr, "view-filter", &f, &used) {
                out.push(Item::Filter(f));
            }
        }
    }
    if has("template") {
        for t in sorted_keys(pr, "view_templates") {
            if !used_guid(pr, "view-template", &t, &graphics) {
                out.push(Item::Template(t));
            }
        }
    }
    out
}

/// Takes an entry of a section away, and the section with its last entry.
fn remove_entry(pr: &mut Project, section: &str, name: &str, drop_empty: bool) {
    let empty = match pr.get_mut(section).and_then(|v| v.as_obj_mut()) {
        Some(m) => {
            m.remove(name);
            m.is_empty()
        }
        None => false,
    };
    if empty && drop_empty {
        pr.remove_top(section);
    }
}

fn take_out(pr: &mut Project, it: &Item) {
    match it {
        Item::CategoryType { cat, loc, name } => {
            if let Some(m) = loc_map_mut(pr, loc) {
                m.remove(name);
            }
            lib_remove(pr, &type_kind(cat), name);
        }
        Item::Family(f) => remove_family(pr, f),
        Item::FamilyType { family, name } => remove_family_type(pr, family, name),
        Item::Material(m) => {
            remove_entry(pr, "materials", m, false);
            lib_remove(pr, "material", m);
        }
        Item::Picture(id) => {
            remove_entry(pr, "images", id, true);
            lib_remove(pr, "picture", id);
        }
        Item::Filter(f) => {
            remove_entry(pr, "view_filters", f, true);
            lib_remove(pr, "view-filter", f);
        }
        Item::Template(t) => {
            remove_entry(pr, "view_templates", t, true);
            lib_remove(pr, "view-template", t);
        }
    }
}

//! Match Properties: the type (and a component's family) of one element given to others.

use super::common::*;
use super::library_util::*;
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;

const C: &str = "match_properties";

pub fn run(s: &mut Session, p: &Value) -> R<Value> {
    match_properties(s, p).map_err(clip_error)
}

fn match_properties(s: &mut Session, p: &Value) -> R<Value> {
    let pr = &mut s.project;
    let Some(fv) = p.get("from") else {
        return Err(format!("{}: `from` (an element id or GUID) is required", C));
    };
    let from = resolve(pr, C, fv)?;
    let fe = pr.el(from).cloned().unwrap_or(Value::Null);
    let Some(ftype) = fe.get("type").and_then(|t| t.as_str()).map(|t| t.to_string()) else {
        return Err(format!("{}: element {} has no type", C, from));
    };
    let ffamily = fe.get("family").and_then(|f| f.as_str()).map(|f| f.to_string());
    let ids = ids_param(pr, C, p)?;
    let cat = cat_of(&fe).to_string();
    let mut modified: Vec<u64> = Vec::new();
    let mut skipped: Vec<u64> = Vec::new();
    for id in ids {
        if id == from {
            continue;
        }
        if pr.category(id) == Some(cat.as_str()) {
            modified.push(id);
        } else {
            skipped.push(id);
        }
    }
    if modified.is_empty() {
        return Err(format!("{}: none of the elements is in the category of element {} ({})", C, from, cat));
    }
    for id in &modified {
        let old_family = pr.el(*id).and_then(|e| e.get("family")).and_then(|f| f.as_str()).map(|f| f.to_string());
        let new_params = match &ffamily {
            Some(nf) if old_family.as_deref() != Some(nf.as_str()) => {
                rekeyed_params(pr, pr.el(*id).unwrap(), old_family.as_deref(), nf)
            }
            _ => None,
        };
        let Some(e) = pr.el_mut(*id) else { continue };
        e.set("type", Value::s(&ftype));
        if let Some(nf) = &ffamily {
            set_family(e, nf);
        }
        if let Some(params) = new_params {
            e.set("params", Value::Obj(params));
        }
    }
    family_types_hold(pr, &modified)?;
    let ids_value = |v: &Vec<u64>| Value::Arr(v.iter().map(|i| Value::u(*i)).collect());
    Ok(jobj! {"modified" => ids_value(&modified), "skipped" => ids_value(&skipped)})
}

/// An element's family set: in its place if it has one, else just after its `type` (a door's or
/// a window's, as the original writes them).
fn set_family(e: &mut Value, family: &str) {
    let Some(m) = e.as_obj_mut() else { return };
    if m.contains("family") {
        m.insert("family", Value::s(family));
        return;
    }
    let pos = m.items.iter().position(|(k, _)| k == "type").map(|i| i + 1).unwrap_or(m.items.len());
    m.items.insert(pos, ("family".to_string(), Value::s(family)));
}

/// An element's own values (`params`) as its new family holds them: a value of a parameter of
/// its old family goes to the new family's parameter of that name (its GUID), or stays under the
/// bare name if the new family has none (which the model's check then refuses); the rest stay.
/// Keys in order, as the original keeps them. None if it holds none.
fn rekeyed_params(pr: &Project, e: &Value, old_family: Option<&str>, new_family: &str) -> Option<Map> {
    let params = e.get("params").and_then(|p| p.as_obj())?;
    let old_name = old_family.and_then(|g| pr.lib_name(g));
    let new_name = pr.lib_name(new_family).unwrap_or_default();
    let mut out = Map::new();
    for (k, v) in params.iter() {
        let entry = crate::model::normalize_guid(k).and_then(|g| {
            pr.library.values().find(|x| x.get("guid").and_then(|y| y.as_str()) == Some(g.as_str()))
        });
        let is_family_param = entry.and_then(|x| x.get("kind")).and_then(|x| x.as_str()) == Some("family-parameter");
        if !is_family_param {
            out.insert(k, v.clone());
            continue;
        }
        let full = entry.and_then(|x| x.get("name")).and_then(|x| x.as_str()).unwrap_or("");
        let pname = match old_name.as_deref().and_then(|o| full.strip_prefix(&format!("{}: ", o))) {
            Some(n) => n.to_string(),
            None => full.split_once(": ").map(|(_, n)| n.to_string()).unwrap_or_else(|| full.to_string()),
        };
        let key = pr.lib_guid("family-parameter", &qualified(&new_name, &pname)).unwrap_or(pname);
        out.insert(&key, v.clone());
    }
    out.sort();
    Some(out)
}

/// The model's rule that an element of a family is of one of its family's types: a door taking a
/// project door type keeps its family, which hasn't that type.
fn family_types_hold(pr: &Project, ids: &[u64]) -> R<()> {
    let mut ids: Vec<u64> = ids.to_vec();
    ids.sort();
    for id in ids {
        let Some(e) = pr.el(id) else { continue };
        let Some(fg) = e.get("family").and_then(|f| f.as_str()) else { continue };
        let Some(fname) = pr.lib_name(fg) else { continue };
        let Some(fam) = families(pr).and_then(|m| m.get(&fname)) else { continue };
        let types = family_type_names(fam);
        let tg = e.get("type").and_then(|t| t.as_str()).unwrap_or("");
        let tname = pr.lib_name(tg).unwrap_or_else(|| tg.to_string());
        let ok = types.iter().any(|t| qualified(&fname, t) == tname);
        if !ok {
            return Err(check_error(format!(
                "{} {}: type `{}` doesn't exist (there are: {})",
                cat_of(e),
                id,
                tname,
                types.join(", ")
            )));
        }
    }
    Ok(())
}

