"""fuzz.py N [seed]: random scripts of purge/delete_type/rename_type/match_properties on fixtures; cmp each."""
import json, os, random, subprocess, sys
MINE = '/workspace/.claude/worktrees/agent-a408f9f6869b9e8e8/target/release/bimcraft-cli'
FX = ['/tmp/edit-library/new.bimcraft', '/tmp/edit-library/s2.bimcraft', '/tmp/edit-library/s4.bimcraft',
      '/tmp/edit-library/s7.bimcraft', '/tmp/edit-library/s8.bimcraft', '/tmp/edit-library/s9.bimcraft',
      '/tmp/edit-library/s10.bimcraft', '/tmp/edit-library/sample.bimcraft', '/tmp/edit-agent/fx/all.bimcraft',
      '/tmp/edit-library/s5.bimcraft', '/tmp/edit-library/s7i.bimcraft']
N = int(sys.argv[1])
seed = int(sys.argv[2]) if len(sys.argv) > 2 else 1
rnd = random.Random(seed)
CAT_WORDS = {'wall': ['wall', 'walls', 'Wall'], 'floor': ['floor', 'Floors'], 'door': ['door', 'doors'], 'window': ['window', 'Windows'],
             'column': ['column'], 'roof': ['roof', 'roofs'], 'ceiling': ['ceiling'], 'railing': ['railing'],
             'structural_column': ['structural column', 'structuralcolumn', 'structural_columns'], 'footing': ['footing'],
             'beam': ['beam', 'beams'], 'cable': ['cable'], 'cabletray': ['cable tray', 'cabletray'], 'conduit': ['conduit'],
             'downconductor': ['down conductor'], 'duct': ['duct'], 'groundconductor': ['ground_conductor'], 'pipe': ['pipe', 'pipes'],
             'stripfooting': ['strip footing'], 'wire': ['wire']}

def pick_cmd(d):
    types = d.get('types', {})
    cats = [c for c in types if c != 'runs']
    runs = list(types.get('runs', {}).keys())
    allcats = [(c, types[c]) for c in cats] + [(c, types['runs'][c]) for c in runs]
    fams = d.get('families', {})
    els = d['elements']
    ids = [int(k) for k in els]
    typed = [int(k) for k, v in els.items() if 'type' in v]
    r = rnd.random()
    if r < 0.25:
        kinds = rnd.sample(['type', 'family', 'material', 'picture', 'filter', 'template'], rnd.randint(0, 6))
        p = {}
        if rnd.random() < 0.8:
            p['kinds'] = kinds
        if rnd.random() < 0.3:
            p['dry_run'] = rnd.random() < 0.5
        return 'purge ' + json.dumps(p)
    if r < 0.5:
        # delete_type
        if rnd.random() < 0.6 and allcats:
            c, ts = rnd.choice(allcats)
            word = rnd.choice(CAT_WORDS.get(c, [c]))
            t = rnd.choice(list(ts.keys()) + ['Nope'])
            return 'delete_type ' + json.dumps({'category': word, 'type': t})
        if fams:
            f = rnd.choice(list(fams.keys()) + ['Nope'])
            p = {'family': f}
            if rnd.random() < 0.6 and f in fams:
                p['type'] = rnd.choice(list(fams[f].get('types', {}).keys()) + ['Nope'])
            return 'delete_type ' + json.dumps(p)
        return 'delete_type {}'
    if r < 0.75:
        name = rnd.choice(['X', 'Y Z', 'Generic - 200mm', 'Exterior - 300mm', '900 x 2000', ' padded ', 'Été', 'Sofa', 'Bed'])
        if rnd.random() < 0.6 and allcats:
            c, ts = rnd.choice(allcats)
            word = rnd.choice(CAT_WORDS.get(c, [c]))
            t = rnd.choice(list(ts.keys()) + ['Nope'])
            if rnd.random() < 0.3:
                name = t
            return 'rename_type ' + json.dumps({'category': word, 'type': t, 'name': name})
        if fams:
            f = rnd.choice(list(fams.keys()) + ['Nope'])
            p = {'family': f, 'name': name}
            if rnd.random() < 0.8 and f in fams:
                tl = list(fams[f].get('types', {}).keys())
                p['type'] = rnd.choice(tl + ['Nope'])
                if rnd.random() < 0.3:
                    p['name'] = rnd.choice(tl)
            return 'rename_type ' + json.dumps(p)
        return 'rename_type {}'
    # match_properties
    if not typed:
        return 'match_properties {}'
    f = rnd.choice(typed)
    same = [i for i in typed if els[str(i)].get('category') == els[str(f)].get('category')]
    pool = same * 3 + ids
    tgt = rnd.sample(pool, min(len(pool), rnd.randint(1, 4)))
    return 'match_properties ' + json.dumps({'from': f, 'ids': tgt})

cache = {}
nd = 0
env = dict(os.environ, MINE=MINE)
for i in range(N):
    fx = rnd.choice(FX)
    if fx not in cache:
        cache[fx] = json.load(open(fx))
    d = cache[fx]
    cmds = [pick_cmd(d) for _ in range(rnd.randint(1, 3))]
    files = []
    for f in ('red.png', 'green.png', 'blue.png'):
        files += ['-f', '/tmp/edit-library/' + f]
    files += ['-f', fx]
    run = ['run', os.path.basename(fx)]
    for c in cmds:
        run += ['--cmd', c]
    run += ['--cmd', 'undo {"count": 1}'] if rnd.random() < 0.2 else []
    run += ['--save', 'out.bimcraft']
    p = subprocess.run(['python3', '/tmp/tools/cmp.py'] + files + ['--'] + run, capture_output=True, text=True, env=env)
    res = p.stdout.strip().splitlines()
    ok = res and res[-1] == 'SAME'
    if not ok:
        nd += 1
        print('DIFF', os.path.basename(fx), ' ;; '.join(cmds)[:400])
        for x in res[:-1][:25]:
            print('    ', x[:300])
print('DIFFS', nd, 'of', N)

