#!/usr/bin/env python3
"""genfx.py N seed: random fixture scripts built with the original into /tmp/edit-library/gen/fxK.bimcraft."""
import json, os, random, subprocess, sys
N = int(sys.argv[1]); seed = int(sys.argv[2])
rnd = random.Random(seed)
os.makedirs('/tmp/edit-library/gen', exist_ok=True)
PICS = ['red.png', 'green.png', 'blue.png']
for k in range(N):
    lines = []
    mats = []
    for i in range(rnd.randint(0, 5)):
        name = 'M%d' % i
        if rnd.random() < 0.4:
            lines.append('material ' + json.dumps({'name': name, 'texture': {'kind': 'image', 'path': rnd.choice(PICS)}}))
        else:
            lines.append('material ' + json.dumps({'name': name}))
        mats.append(name)
    allmats = mats + ['Brick', 'Concrete', 'Timber', 'Glass', 'Plaster', 'Screed']
    wtypes = ['Generic - 200mm', 'Exterior - 300mm', 'Interior - 100mm']
    for i in range(rnd.randint(0, 3)):
        name = rnd.choice(['WT%d' % i, 'A wall %d' % i, 'Zz %d' % i])
        if name in wtypes:
            continue
        layers = [{'function': 'structure', 'material': rnd.choice(allmats), 'thickness': 100 + 10 * i}]
        if rnd.random() < 0.5:
            layers.insert(0, {'function': 'finish', 'material': rnd.choice(allmats), 'thickness': 20})
        lines.append('type ' + json.dumps({'category': 'wall', 'name': name, 'layers': layers}))
        wtypes.append(name)
    ftypes = ['Generic - 200mm']
    if rnd.random() < 0.5:
        lines.append('type ' + json.dumps({'category': 'floor', 'name': 'FT', 'layers': [{'function': 'structure', 'material': rnd.choice(allmats), 'thickness': 150}]}))
        ftypes.append('FT')
    btypes = ['Beam 150 x 400', 'Beam 200 x 500', 'Steel Tube 150']
    if rnd.random() < 0.5:
        lines.append('type ' + json.dumps({'category': 'beam', 'name': 'BT', 'width': 250, 'depth': 450, 'material': rnd.choice(allmats)}))
        btypes.append('BT')
    fams = ['Bed', 'Sofa', 'Chair', 'Desk', 'Table']
    for i in range(rnd.randint(0, 2)):
        name = 'Fam%d' % i
        params = [{'name': 'W', 'kind': 'length', 'value': 500}, {'name': 'Mat', 'kind': 'material', 'value': rnd.choice(allmats)}]
        types = {'T1': {}, 'T2': {'W': 700}}
        if rnd.random() < 0.5:
            types['T3'] = {'Mat': rnd.choice(allmats)}
        lines.append('family ' + json.dumps({'name': name, 'category': 'furniture', 'parameters': params, 'types': types,
                                              'forms': [{'profile': [[0, 0], ['W', 0], ['W', 500], [0, 500]], 'to': 500, 'material': 'Mat'}]}))
        fams.append(name)
    # house
    wt = rnd.choice(wtypes)
    lines.append('wall ' + json.dumps({'points': [[0, 0], [8000, 0], [8000, 6000], [0, 6000]], 'closed': True, 'type': wt}))
    if rnd.random() < 0.6:
        lines.append('wall ' + json.dumps({'points': [[4000, 0], [4000, 6000]], 'type': rnd.choice(wtypes)}))
    if rnd.random() < 0.6:
        lines.append('door ' + json.dumps({'at': [2000, 0], 'type': rnd.choice(['Single 800 x 2100', 'Single 900 x 2100'])}))
    if rnd.random() < 0.4:
        lines.append('door ' + json.dumps({'at': [6000, 0], 'family': rnd.choice(['Double Door', 'Single Door'])}))
    if rnd.random() < 0.5:
        lines.append('window ' + json.dumps({'at': [8000, 3000], 'type': rnd.choice(['Fixed 1200 x 1500', 'Fixed 600 x 900'])}))
    if rnd.random() < 0.3:
        lines.append('window ' + json.dumps({'at': [0, 3000], 'family': 'Casement Window'}))
    if rnd.random() < 0.5:
        lines.append('floor ' + json.dumps({'type': rnd.choice(ftypes)}))
    for i in range(rnd.randint(0, 3)):
        f = rnd.choice(fams)
        lines.append('component ' + json.dumps({'family': f, 'at': [1000 + 1500 * i, 2000]}))
    if rnd.random() < 0.4:
        lines.append('beam ' + json.dumps({'points': [[10000, 0], [10000, 4000]], 'level': 'Level 2', 'type': rnd.choice(btypes)}))
    if rnd.random() < 0.3:
        lines.append('paint ' + json.dumps({'id': 100002, 'face': 'exterior', 'material': rnd.choice(allmats)}))
    filters = []
    for i in range(rnd.randint(0, 3)):
        lines.append('filter ' + json.dumps({'name': 'F%d' % i, 'categories': [rnd.choice(['walls', 'doors', 'rooms'])]}))
        filters.append('F%d' % i)
    temps = []
    for i in range(rnd.randint(0, 2)):
        p = {'name': 'T%d' % i, 'kind': 'plan'}
        if filters and rnd.random() < 0.6:
            p['filters'] = [{'filter': rnd.choice(filters), 'halftone': True}]
        lines.append('template ' + json.dumps(p))
        temps.append('T%d' % i)
    if filters and rnd.random() < 0.5:
        lines.append('graphics ' + json.dumps({'view': 'Level 1', 'filters': [{'filter': rnd.choice(filters), 'halftone': True}]}))
    if temps and rnd.random() < 0.5:
        lines.append('graphics ' + json.dumps({'view': 'Level 2', 'template': rnd.choice(temps)}))
    d = '/tmp/edit-library/gen'
    open(os.path.join(d, 'fx%d.txt' % k), 'w').write('\n'.join(lines) + '\n')
    p = subprocess.run(['/workspace/executable', 'run', '--script', 'fx%d.txt' % k, '--save', 'fx%d.bimcraft' % k], cwd=d, capture_output=True, text=True)
    if p.returncode != 0:
        print('fx%d failed:' % k, p.stderr.strip()[:300])
print('done')

